"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[6822],{3070:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/09/17/net-format-change","metadata":{"permalink":"/announcements/2026/09/17/net-format-change","source":"@site/blog/2026-09-17-net-format-change.md","title":"Weekly Training Net Repeater Change","description":"The PACT Weekly Training Net will continue using its two-part format, with check-ins on 439.800 MHz simplex followed by announcements, traffic, and training on the new Provo City Repeater.","date":"2026-09-17T00:00:00.000Z","tags":[{"inline":false,"label":"Training Exercises & Events","permalink":"/announcements/tags/training","description":"PACT Training Exercises and Events."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Weekly Training Net Repeater Change","description":"The PACT Weekly Training Net will continue using its two-part format, with check-ins on 439.800 MHz simplex followed by announcements, traffic, and training on the new Provo City Repeater.","date":"2026-09-17T00:00:00.000Z","tags":["training"]},"unlisted":false,"nextItem":{"title":"New Provo City Repeater","permalink":"/announcements/2026/09/16/provo-city-repeater"}},"content":"The format of the PACT Weekly Training Net is staying the same, but the repeater used for the second portion of the net is changing.\\n\\nThe net will continue to be held every Wednesday at **2030 hrs (8:30 PM)** using the same two-part format.\\n\\n## 1. Check-Ins\\n\\nThe net will begin with member check-ins on:\\n\\n**439.800 MHz Simplex**\\n\\nAfter check-ins are complete, participants will switch to the **Provo City Repeater** for the remainder of the net.\\n\\n## 2. Announcements & Training\\n\\nAnnouncements, traffic, and the weekly training topic will now take place on the Provo City Repeater instead of the \'47 repeater:\\n\\n**Provo City Repeater**  \\n**Output (RX):** 443.575 MHz  \\n**Input (TX):** 448.575 MHz  \\n**CTCSS:** 123.0 Hz\\n\\nMembers are encouraged to participate each Wednesday to practice radio procedures, stay informed, and build familiarity with PACT communications.\\n\\nFor complete net information and procedures, visit the [Weekly Training Net](/docs/training/weekly-training-net/) page.\\n\\n\x3c!-- truncate --\x3e\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/09/16/provo-city-repeater","metadata":{"permalink":"/announcements/2026/09/16/provo-city-repeater","source":"@site/blog/2026-09-16-provo-city-repeater.md","title":"New Provo City Repeater","description":"A new amateur radio repeater is now available at Provo City Hall.","date":"2026-09-16T00:00:00.000Z","tags":[{"inline":true,"label":"General Announcements","permalink":"/announcements/tags/general-announcements"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"New Provo City Repeater","description":"A new amateur radio repeater is now available at Provo City Hall.","date":"2026-09-16T00:00:00.000Z","tags":["General Announcements"]},"unlisted":false,"prevItem":{"title":"Weekly Training Net Repeater Change","permalink":"/announcements/2026/09/17/net-format-change"},"nextItem":{"title":"November Interface Date Change","permalink":"/announcements/2026/08/19/interface-date-change"}},"content":"Provo City has installed a new amateur radio repeater at Provo City Hall. The repeater will be available for use beginning **September 17, 2026**.\\n\\nPACT would like to thank Provo City for installing the repeater and making it available for all PACT operations and communications.\\n\\n### Provo City Repeater\\n\\n**Input (TX):** 448.575 MHz  \\n**Output (RX):** 443.575 MHz  \\n**CTCSS:** 123.0 Hz  \\n**Location:** Provo City Hall\\n\\n\x3c!-- truncate --\x3e\\n\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/08/19/interface-date-change","metadata":{"permalink":"/announcements/2026/08/19/interface-date-change","source":"@site/blog/2026-08-19-interface-date-change.md","title":"November Interface Date Change","description":"The November PACT Interface Meeting has been rescheduled to November 18, 2026, at Provo Fire Station 22.","date":"2026-08-19T00:00:00.000Z","tags":[{"inline":false,"label":"Interface Meetings","permalink":"/announcements/tags/interface-meetings","description":"PACT Interface Meetings."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"November Interface Date Change","description":"The November PACT Interface Meeting has been rescheduled to November 18, 2026, at Provo Fire Station 22.","date":"2026-08-19T00:00:00.000Z","tags":["meetings"]},"unlisted":false,"prevItem":{"title":"New Provo City Repeater","permalink":"/announcements/2026/09/16/provo-city-repeater"},"nextItem":{"title":"Weekly Training Net Format Change","permalink":"/announcements/2026/07/21/net-format-change"}},"content":"The upcoming PACT Interface Meeting has been rescheduled. Please update your calendars with the new date.\\n\\n### New Meeting Date\\n\\n**Date:** November 18, 2026  \\n**Time:** 7:00\u20138:00 PM  \\n**Location:** Provo Fire Station 22 \u2013 Community Room  \\n**Address:** 2737 N Canyon Rd, Provo, UT 84604\\n\\nWe look forward to seeing you there!\\n\\n\x3c!-- truncate --\x3e\\n\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/07/21/net-format-change","metadata":{"permalink":"/announcements/2026/07/21/net-format-change","source":"@site/blog/2026-07-21-net-format-change.md","title":"Weekly Training Net Format Change","description":"The PACT Weekly Training Net now begins with check-ins on 439.800 MHz simplex before moving to the \'47 Repeater for announcements, traffic, and training.","date":"2026-07-21T00:00:00.000Z","tags":[{"inline":false,"label":"Training Exercises & Events","permalink":"/announcements/tags/training","description":"PACT Training Exercises and Events."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"Weekly Training Net Format Change","description":"The PACT Weekly Training Net now begins with check-ins on 439.800 MHz simplex before moving to the \'47 Repeater for announcements, traffic, and training.","date":"2026-07-21T00:00:00.000Z","tags":["training"]},"unlisted":false,"prevItem":{"title":"November Interface Date Change","permalink":"/announcements/2026/08/19/interface-date-change"},"nextItem":{"title":"PACT Apparel Now Available","permalink":"/announcements/2026/05/21/pact-apparel-now-available"}},"content":"The PACT Weekly Training Net has a new format!\\n\\nThe net will continue to be held every Wednesday at 2030 hrs (8:30 PM), but we will now use a two-part format.\\n\\n## 1. Check-Ins\\n\\nThe net will begin with member check-ins on:\\n\\n**439.800 MHz Simplex**\\n\\nAfter check-ins are complete, participants will switch to the **\'47 Repeater** for the remainder of the net.\\n\\n## 2. Announcements & Training\\n\\nThe second portion of the net will include announcements, traffic, and a weekly training topic on the \'47 Repeater:\\n\\n**\'47 Repeater**  \\n**RX:** 444.325 MHz  \\n**TX:** 449.325 MHz  \\n**CTCSS:** 100.0 Hz\\n\\nMembers are encouraged to participate each Wednesday to practice radio procedures, stay informed, and build familiarity with PACT communications.\\n\\nFor complete net information and procedures, visit the [Weekly Training Net](/docs/training/weekly-training-net/) page.\\n\\n\x3c!-- truncate --\x3e\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/05/21/pact-apparel-now-available","metadata":{"permalink":"/announcements/2026/05/21/pact-apparel-now-available","source":"@site/blog/2026-05-21-pact-apparel-now-available.md","title":"PACT Apparel Now Available","description":"PACT-branded shirts, hats, vests, patches, and other apparel are now available for members to order.","date":"2026-05-21T00:00:00.000Z","tags":[{"inline":false,"label":"General Announcements","permalink":"/announcements/tags/general-announcements","description":"Important PACT updates and other general notices."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"PACT Apparel Now Available","description":"PACT-branded shirts, hats, vests, patches, and other apparel are now available for members to order.","date":"2026-05-21T00:00:00.000Z","tags":["general-announcement"]},"unlisted":false,"prevItem":{"title":"Weekly Training Net Format Change","permalink":"/announcements/2026/07/21/net-format-change"},"nextItem":{"title":"PACT Is Now On LinkedIn","permalink":"/announcements/2026/03/04/pact-is-on-linkedin"}},"content":"PACT-branded apparel is now available for members to order!\\n\\nMembers can choose from a variety of PACT clothing and gear, including shirts, hats, vests, patches, and other items.\\n\\nWearing PACT apparel helps identify team members and promotes a consistent, professional team presence during training, public service events, and emergency operations.\\n\\nVisit the PACT Clothing page to view available items, ordering information, and current options.\\n\\n<div\\n  style={{\\n    marginTop: \'1.5rem\',\\n    marginBottom: \'2rem\',\\n    textAlign: \'center\',\\n  }}\\n>\\n  <a\\n    href=\\"/docs/resources/clothing/\\"\\n    className=\\"button button--primary button--lg\\"\\n  >\\n    View PACT Apparel\\n  </a>\\n</div>\\n\\n\x3c!-- truncate --\x3e\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/03/04/pact-is-on-linkedin","metadata":{"permalink":"/announcements/2026/03/04/pact-is-on-linkedin","source":"@site/blog/2026-03-04-pact-is-on-linkedin.md","title":"PACT Is Now On LinkedIn","description":"Connect with the Provo Auxiliary Communications Team on LinkedIn and add your PACT service to your Volunteer Experience.","date":"2026-03-04T00:00:00.000Z","tags":[{"inline":false,"label":"General Announcements","permalink":"/announcements/tags/general-announcements","description":"Important PACT updates and other general notices."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"PACT Is Now On LinkedIn","description":"Connect with the Provo Auxiliary Communications Team on LinkedIn and add your PACT service to your Volunteer Experience.","date":"2026-03-04T00:00:00.000Z","tags":["general-announcement"]},"unlisted":false,"prevItem":{"title":"PACT Apparel Now Available","permalink":"/announcements/2026/05/21/pact-apparel-now-available"},"nextItem":{"title":"PACT Telegram Group","permalink":"/announcements/2026/01/01/pact-telegram-group"}},"content":"PACT is now on LinkedIn!\\n\\nPACT members can add the Provo Auxiliary Communications Team to the Volunteer Experience section of their LinkedIn profiles. It\'s a great way to highlight your volunteer service, emergency communications experience, and commitment to community preparedness.\\n\\n<div style={{ textAlign: \'center\', margin: \'1.5rem 0\' }}>\\n  <img\\n    src=\\"/img/linkedin.jpg\\"\\n    alt=\\"PACT listed as volunteer experience on LinkedIn\\"\\n    style={{\\n      width: \'100%\',\\n      maxWidth: \'800px\',\\n      borderRadius: \'10px\',\\n    }}\\n  />\\n</div>\\n\\nIf you serve with PACT, consider adding the team to your profile and following the PACT LinkedIn page for team updates and information.\\n\\n<div\\n  style={{\\n    marginTop: \'1.5rem\',\\n    marginBottom: \'2rem\',\\n    textAlign: \'center\',\\n  }}\\n>\\n  <a\\n    href=\\"https://www.linkedin.com/company/provo-auxiliary-communications-team-pact/about/\\"\\n    className=\\"button button--primary button--lg\\"\\n    target=\\"_blank\\"\\n    rel=\\"noopener noreferrer\\"\\n  >\\n    Visit PACT on LinkedIn\\n  </a>\\n</div>\\n\\n\x3c!-- truncate --\x3e\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"},{"id":"/2026/01/01/pact-telegram-group","metadata":{"permalink":"/announcements/2026/01/01/pact-telegram-group","source":"@site/blog/2026-01-01-pact-telegram-group.md","title":"PACT Telegram Group","description":"Join the PACT Telegram group for team announcements, training updates, activation notifications, and other important communications.","date":"2026-01-01T00:00:00.000Z","tags":[{"inline":false,"label":"General Announcements","permalink":"/announcements/tags/general-announcements","description":"Important PACT updates and other general notices."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"PACT Telegram Group","description":"Join the PACT Telegram group for team announcements, training updates, activation notifications, and other important communications.","date":"2026-01-01T00:00:00.000Z","tags":["general-announcement"]},"unlisted":false,"prevItem":{"title":"PACT Is Now On LinkedIn","permalink":"/announcements/2026/03/04/pact-is-on-linkedin"}},"content":"Telegram is PACT\'s primary platform for team announcements, training updates, activation notifications, and other important communications.\\n\\nAll PACT members are encouraged to join the group so they can stay informed and receive timely information from the team.\\n\\n<div\\n  style={{\\n    marginTop: \'1.5rem\',\\n    marginBottom: \'2rem\',\\n    textAlign: \'center\',\\n  }}\\n>\\n  <a\\n    href=\\"https://t.me/+M5nUHsEYmoI1ZDQx\\"\\n    className=\\"button button--primary button--lg\\"\\n    target=\\"_blank\\"\\n    rel=\\"noopener noreferrer\\"\\n  >\\n    Join the PACT Telegram Group\\n  </a>\\n</div>\\n\\n\x3c!-- truncate --\x3e\\n---\\n\\n<div className=\\"announcement-signature\\">\\n  <img\\n    src=\\"/img/pact-logo.png\\"\\n    alt=\\"PACT Logo\\"\\n  />\\n\\n  <div>\\n    <strong>PACT Leadership Team</strong>\\n    <span>Provo Auxiliary Communications Team</span>\\n  </div>\\n</div>"}]}}')}}]);